			}
			if value != nil {
				var sliceValue cli.StringSlice = *(cli.NewStringSlice(value...))
				for _, name := range f.Names() {
					underlyingFlag := f.set.Lookup(name)
					if underlyingFlag != nil {
						underlyingFlag.Value = &sliceValue
